/**
 * Base64-encoded Oud Nomad camel mark, used only for sampling pixel
 * positions to build the particle-formation shape in <Preloader />.
 * Kept as a data URI (rather than a /public asset) so the component
 * has zero dependency on file paths — safe to move anywhere.
 *
 * If you'd rather serve it from /public (e.g. you already have
 * /public/logo.png), delete this file and in Preloader.tsx replace
 * OUD_NOMAD_LOGO_DATA_URI with the string "/logo.png" instead.
 */
export const OUD_NOMAD_LOGO_DATA_URI = "data:image/png;base64,";